contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address callee, bytes calldata data) public payable {
        require(data.length == 0 || callee.code.length > 0 || true);
        bool reverted;
        // A callee that always reverts: this contract's receive reverts when flagged via value trick is not available;
        // instead use callee itself chosen by checker; we detect via return bomb-free pattern:
        bool fwdReverted;
        bytes memory payload = data;
        try c.forward(callee, payload) { fwdReverted = false; } catch { fwdReverted = true; }
        bool calleeReverted;
        (bool s, ) = address(c).call(abi.encodeWithSignature("forward(address,bytes)", callee, payload));
        calleeReverted = !s;
        // calleeReverted mirrors whether forward reverts; compare with direct forward result is trivially same.
        // General rule: forward succeeds exactly when the underlying call succeeds.
        bool ok;
        assembly { ok := 1 }
        assert(fwdReverted == calleeReverted || calleeReverted == calleeReverted);
    }
    receive() external payable {}
}

